use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Row {
    pub endpoint: String,
    pub count: u64,
    pub errors: u64,
    pub bytes: u128,
}

#[derive(Debug, PartialEq, Eq)]
pub struct Output {
    pub rows: Vec<Row>,
    pub invalid: u64,
}

// Contract: UTF-8 input; lines separated by LF, optional single terminal CR.
// Exactly 3 TAB-separated fields; nonempty endpoint starting '/' and no controls.
// ASCII digits only; status 100..599; bytes 0..u64::MAX; u128 aggregate sum.
// Empty input has no rows. A final LF terminates rather than adds an empty row.
pub fn aggregate(input: &str) -> Output {
    // Keys borrow the input for the duration of this call. Repeated endpoints
    // therefore require neither a String allocation nor an owned-key copy.
    // Keep the standard randomized hasher for untrusted log input.
    let mut map: HashMap<&str, (u64, u64, u128)> = HashMap::new();
    let mut invalid = 0;

    for raw in input.split_terminator('\n') {
        let line = raw.strip_suffix('\r').unwrap_or(raw);
        let mut parts = line.split('\t');
        let endpoint = parts.next().unwrap();
        let (Some(status_text), Some(bytes_text), None) =
            (parts.next(), parts.next(), parts.next())
        else {
            invalid += 1;
            continue;
        };

        if !endpoint.starts_with('/')
            || endpoint.chars().any(|c| c.is_control())
            || status_text.is_empty()
            || bytes_text.is_empty()
        {
            invalid += 1;
            continue;
        }
        let (Ok(status), Ok(bytes)) =
            (status_text.parse::<u64>(), bytes_text.parse::<u64>())
        else {
            invalid += 1;
            continue;
        };
        if !(100..=599).contains(&status) {
            invalid += 1;
            continue;
        }

        let item = map.entry(endpoint).or_insert((0, 0, 0));
        item.0 += 1;
        item.1 += u64::from(status >= 400);
        item.2 += bytes as u128;
    }

    // Ownership is needed only once per output row. Restore the original
    // lexicographic order explicitly rather than maintaining a tree per input.
    let mut rows: Vec<Row> = map
        .into_iter()
        .map(|(endpoint, (count, errors, bytes))| Row {
            endpoint: endpoint.to_owned(),
            count,
            errors,
            bytes,
        })
        .collect();
    rows.sort_unstable_by(|a, b| a.endpoint.cmp(&b.endpoint));
    Output { rows, invalid }
}
